<?php

declare(strict_types=1);

namespace App\Hosts\Protocol;

use App\Attributes\Generation\AutoGenerated;
use Spatie\LaravelData\Data;

/**
 * Every instruction of host protocol 1, the whole vocabulary a host carries out.
 * Generated by php artisan journal:host-protocol from protocol/host.json; do not edit.
 */
#[AutoGenerated('protocol/host.json')]
enum HostInstructionType: string
{
    case OpenContainer = 'open_container';
    case OpenProcess = 'open_process';
    case WriteKeys = 'write_keys';
    case WriteStdin = 'write_stdin';
    case CloseStdin = 'close_stdin';
    case OpenPrivate = 'open_private';
    case WritePrivate = 'write_private';
    case ClosePrivate = 'close_private';
    case Resize = 'resize';
    case Signal = 'signal';
    case Stop = 'stop';
    case Stream = 'stream';
    case Snapshot = 'snapshot';
    case RunFenced = 'run_fenced';
    case AllowImages = 'allow_images';
    case RunContainers = 'run_containers';
    case ListContainers = 'list_containers';
    case RemoveNetwork = 'remove_network';
    case Remove = 'remove';
    case ReadProject = 'read_project';
    case Upgrade = 'upgrade';

    /**
     * Whether the instruction ends its process, so a process that ended still lets its host answer it.
     */
    public function endsProcess(): bool
    {
        return in_array($this, [
            self::Stop,
            self::Remove,
        ], true);
    }

    public function isInput(): bool
    {
        return in_array($this, [
            self::WriteKeys,
            self::WriteStdin,
            self::CloseStdin,
            self::WritePrivate,
        ], true);
    }

    /**
     * Whether a claim of this instruction cut off by the host's restart is offered to the new process:
     * never an input, which is never written twice, nor an instruction the journal gives anew after a
     * restart.
     */
    public function isOfferedAgainAfterRestart(): bool
    {
        return ! in_array($this, [
            self::WriteKeys,
            self::WriteStdin,
            self::CloseStdin,
            self::WritePrivate,
            self::AllowImages,
        ], true);
    }

    /**
     * Whether this instruction opens a process, so its payload carries the process's environment.
     */
    public function isOpening(): bool
    {
        return in_array($this, [
            self::OpenContainer,
            self::OpenProcess,
        ], true);
    }

    /**
     * Whether this instruction can be carried out on a process of that type: keys and screens need a terminal,
     * standard input needs pipes.
     */
    public function suits(HostProcessType $type): bool
    {
        return match (true) {
            in_array($this, [
                self::WriteKeys,
                self::Resize,
                self::Stream,
                self::Snapshot,
            ], true) => $type === HostProcessType::Terminal,
            in_array($this, [
                self::WriteStdin,
                self::CloseStdin,
            ], true) => $type === HostProcessType::Pipe,
            default => true,
        };
    }

    /**
     * The Data of the payload this instruction carries.
     *
     * @return class-string<Data>
     */
    public function payloadOf(): string
    {
        return match ($this) {
            self::OpenContainer, self::OpenProcess => Payloads\HostOpenPlanPayload::class,
            self::WriteKeys => Payloads\HostKeyWritePayload::class,
            self::WriteStdin => Payloads\HostStdinWritePayload::class,
            self::CloseStdin, self::OpenPrivate, self::ClosePrivate, self::Snapshot => Payloads\HostEmptyPayload::class,
            self::WritePrivate => Payloads\HostPrivateWritePayload::class,
            self::Resize => Payloads\HostTerminalSizePayload::class,
            self::Signal => Payloads\HostSignalPlanPayload::class,
            self::Stop => Payloads\HostStopPlanPayload::class,
            self::Stream => Payloads\HostStreamPlanPayload::class,
            self::RunFenced => Payloads\HostFencedPlanPayload::class,
            self::AllowImages => Payloads\HostImagesPlanPayload::class,
            self::RunContainers => Payloads\HostContainerRunsPayload::class,
            self::ListContainers => Payloads\HostContainerLabelPayload::class,
            self::RemoveNetwork => Payloads\HostNetworkRemovalPayload::class,
            self::Remove => Payloads\HostRemovePlanPayload::class,
            self::ReadProject => Payloads\HostProjectReadPayload::class,
            self::Upgrade => Payloads\HostUpgradePlanPayload::class,
        };
    }

    /**
     * The Data a done answer of this instruction carries as its facts.
     *
     * @return class-string<Data>
     */
    public function replyPayload(): string
    {
        return match ($this) {
            self::OpenContainer, self::OpenProcess => Payloads\HostOpenedPayload::class,
            self::WriteKeys => Payloads\HostKeysWrittenPayload::class,
            self::WriteStdin,
            self::CloseStdin,
            self::OpenPrivate,
            self::WritePrivate,
            self::ClosePrivate,
            self::Resize,
            self::Signal,
            self::Stop,
            self::Stream,
            self::Snapshot,
            self::RemoveNetwork,
            self::Remove,
            self::ReadProject => Payloads\HostEmptyPayload::class,
            self::RunFenced => Payloads\HostFencedResultsPayload::class,
            self::AllowImages => Payloads\HostImagesAllowedPayload::class,
            self::RunContainers => Payloads\HostContainerRunResultsPayload::class,
            self::ListContainers => Payloads\HostContainerNamesPayload::class,
            self::Upgrade => Payloads\HostUpgradeStartedPayload::class,
        };
    }
}
